static ToolFeatures full_features(void){ToolFeatures f={0};f.camera=f.camera_fps=f.require_audio=f.no_downsize=f.display_orientation=f.window_size=f.zoom=f.mic_sources=true;return f;}
static void adb_tests(void){
    DeviceList *l=calloc(1,sizeof(*l)),*snapshot=calloc(1,sizeof(*snapshot));
    const char *fake="* daemon started successfully\nList of devices attached\nPHONE_A device product:x model:Pixel_10_Pro_XL transport_id:1\nPHONE_B unauthorized usb:2-1 transport_id:2\n192.168.1.7:39391 offline transport_id:3\nemulator-5554 device model:Test_Emulator transport_id:4\nPHONE_C recovery\nPHONE_D future-state model:Same_Model\nPHONE_E device model:Same_Model transport_id:7\nPHONE_F device model:Same_Model transport_id:8\n";
    CHECK(parse_adb_devices(fake,l));CHECK(l->count==8);CHECK(l->items[0].state==DEV_AUTHORIZED);CHECK(!strcmp(l->items[0].model,"Pixel 10 Pro XL"));CHECK(l->items[1].state==DEV_UNAUTHORIZED);CHECK(l->items[2].state==DEV_OFFLINE);CHECK(l->items[2].transport==TRANSPORT_WIRELESS);CHECK(l->items[3].transport==TRANSPORT_EMULATOR);CHECK(l->items[4].state==DEV_UNSUPPORTED);CHECK(l->items[5].state==DEV_UNKNOWN);CHECK(!strcmp(l->items[5].raw_state,"future-state"));CHECK(find_device(l,"PHONE_E","7")==6);CHECK(find_device(l,"PHONE_E","8")==-1);CHECK(find_device(l,"PHONE_F","")==7);
    CHECK(parse_adb_devices("List of devices attached\nPHONE_A offline transport_id:1\nPHONE_B device model:Another_Phone transport_id:2\n",snapshot));snapshot->items[1].sdk=37;awm_copy(snapshot->items[1].android,64,"17");merge_devices(l,snapshot);CHECK(l->items[0].state==DEV_OFFLINE);CHECK(l->items[1].state==DEV_AUTHORIZED);CHECK(l->items[1].sdk==37);CHECK(l->items[2].state==DEV_DISCONNECTED);CHECK(!parse_adb_devices("error: no devices",snapshot));CHECK(!parse_adb_devices("garbage",snapshot));
    free(l);free(snapshot);
}
