    HANDLE corrupt=CreateFileW(path,GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);CHECK(corrupt!=INVALID_HANDLE_VALUE);if(corrupt!=INVALID_HANDLE_VALUE){DWORD n=0;CHECK(WriteFile(corrupt,"FAKE corrupt configuration",26,&n,NULL));CloseHandle(corrupt);}config_defaults(b);CHECK(!config_load(path,b,err,sizeof(err)));CHECK(b->profile_count==0&&b->obs_port==4455);DeleteFileW(path);
    AudioMeter m;CHECK(!audio_meter_open(&m,L"{nonexistent-fake-endpoint}",err,sizeof(err)));CHECK(!audio_endpoint_active(L"{nonexistent-fake-endpoint}",eCapture));
    wchar_t self[AWM_PATH];GetModuleFileNameW(NULL,self,AWM_PATH);Arguments *args=calloc(1,sizeof(*args));args_add(args,self);args_add(args,L"--child-argv");args_add(args,L"工具 space and \"quote\"");args_add(args,L"ends\\");char output[4096];DWORD code=0;CHECK(process_run(args,NULL,NULL,NULL,5000,output,sizeof(output),&code,err,sizeof(err)));CHECK(code==0);CHECK(strstr(output,"工具 space and \"quote\"")!=NULL);CHECK(strstr(output,"ends\\")!=NULL);
    args->count=1;args_add(args,L"--child-fail");CHECK(process_run(args,NULL,NULL,NULL,5000,output,sizeof(output),&code,err,sizeof(err)));CHECK(code==7);
    args->count=1;args_add(args,L"--child-wait");CHECK(!process_run(args,NULL,NULL,NULL,150,output,sizeof(output),&code,err,sizeof(err)));Process owned;CHECK(process_start(&owned,args,NULL,NULL,true,err,sizeof(err)));DWORD pid=owned.pid;process_close(&owned);HANDLE dead=OpenProcess(SYNCHRONIZE,FALSE,pid);CHECK(!dead||WaitForSingleObject(dead,1000)==WAIT_OBJECT_0);if(dead)CloseHandle(dead);
